// Mouse drag + tap-to-place-marker.
var dragging = false, lastX = 0, lastY = 0, downX = 0, downY = 0, totalMove = 0;
mapEl.addEventListener("mousedown", function(e) {
  dragging = true; lastX = e.clientX; lastY = e.clientY; downX = e.clientX; downY = e.clientY; totalMove = 0;
});
window.addEventListener("mousemove", function(e) {
  if (!dragging) return;
  totalMove += Math.abs(e.clientX - lastX) + Math.abs(e.clientY - lastY);
  pan(lastX - e.clientX, lastY - e.clientY);
  lastX = e.clientX; lastY = e.clientY;
});
window.addEventListener("mouseup", function() {
  if (dragging && totalMove < 6) placeMarker(lastX, lastY);
  dragging = false;
});
mapEl.addEventListener("wheel", function(e) {
  e.preventDefault();
  if (e.deltaY < 0) zoomIn(); else zoomOut();
});

function placeMarker(x, y) {
  var rect = mapEl.getBoundingClientRect();
  var mk = document.createElement("div");
  mk.className = "marker";
  mk.style.left = (x - rect.left) + "px";
  mk.style.top = (y - rect.top) + "px";
  var lbl = document.getElementById("heading-label");
  mk.title = "立向点 " + (lbl ? lbl.textContent : "");
  mapEl.appendChild(mk);
}

function clearMarkers() {
  var ms = mapEl.querySelectorAll(".marker");
  for (var i = 0; i < ms.length; i++) ms[i].remove();
}

// Touch.
var t = null;
mapEl.addEventListener("touchstart", function(e) {
  if (e.touches.length === 1) { t = { x: e.touches[0].clientX, y: e.touches[0].clientY }; }
}, { passive: true });
mapEl.addEventListener("touchmove", function(e) {
  if (e.touches.length === 1 && t) {
    var dx = e.touches[0].clientX - t.x, dy = e.touches[0].clientY - t.y;
    t = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    pan(-dx, -dy);
  }
}, { passive: true });
mapEl.addEventListener("touchend", function(e) {
  if (t) { placeMarker(t.x, t.y); t = null; }
});

window.addEventListener("resize", render);
render();

